import{at as e,it as t,n,vt as r}from"./chunks/framework.B0lbOe_c.js";var i=JSON.parse(`{"title":"Data lineage","description":"","frontmatter":{"title":"Data lineage","covers":{"screens":[],"stories":["US-063","US-064","US-065","US-068"]}},"headers":[],"relativePath":"usage/data-lineage.md","filePath":"usage/data-lineage.md"}`),a={name:`usage/data-lineage.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="data-lineage" tabindex="-1">Data lineage <a class="header-anchor" href="#data-lineage" aria-label="Permalink to “Data lineage”">​</a></h1><p>Data lineage shows how data flows between systems: where a data object comes from and where it goes. You model it with ordinary entities and connections and query it through the API. The page that draws the lineage follows in a later release; this page covers modelling and the query.</p><p>You need <code>entity:read</code> (for example the role <code>viewer</code>) to query the lineage and to filter catalogs, and <code>entity:write</code> (role <code>enterprise-architect</code>) to model it. The types come with the TOGAF starter package 1.5.0 (see <a href="./../administration/metamodel-packages#lineage-types">Lineage types</a>); which types play which part is set in the <a href="./../administration/metamodel-editing#lineage-model">lineage model</a>.</p><h2 id="model-data-flows-and-the-data-they-carry" tabindex="-1">Model data flows and the data they carry <a class="header-anchor" href="#model-data-flows-and-the-data-they-carry" aria-label="Permalink to “Model data flows and the data they carry”">​</a></h2><ol><li>Create the <em>Data Object</em>, for example <em>Customer Master</em>, and give it optional properties: <em>Data classification</em>, <em>Personal data categories</em> and <em>Data owner</em>.</li><li>Connect two systems by a <em>Data Flow</em>, for example from <em>SAP ERP</em> to <em>DWH</em>. A data flow runs between application components, application services, technology components and system software; its optional properties are <em>Protocol</em>, <em>Frequency</em>, <em>Personal data categories</em> and <em>Transformation description</em>.</li><li>Connect the data flow to the data object by <em>Carries Data</em>. The source of this connection is the <strong>data flow</strong>, not a system: a connection that starts at a connection. A flow can carry several data objects, and a data object can be carried by several flows.</li></ol><p>A <em>Carries Data</em> from an application component is refused with <code>422 SOURCE_NOT_ALLOWED</code>, one to a data flow with <code>422 TARGET_NOT_ALLOWED</code>. Connections of connections go <strong>one level deep</strong>: a new connection whose source or target is itself a connection at a connection (for example a <em>Realized By</em> at a <em>Carries Data</em>) is refused with <code>422 CONNECTION_DEPTH_EXCEEDED</code>, which names the source or the target. Connections that exist stay.</p><p>Tasks join the lineage through the BPMN data associations: a task with a <em>Data Output Association</em> to a data object is a <strong>writer</strong>, shown upstream with its <em>Transformation type</em>; a task with a <em>Data Input Association</em> from the data object is a <strong>reader</strong>, shown downstream.</p><h2 id="query-the-lineage" tabindex="-1">Query the lineage <a class="header-anchor" href="#query-the-lineage" aria-label="Permalink to “Query the lineage”">​</a></h2><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/views/lineage/query&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;startEntityId&quot;: 42, &quot;direction&quot;: &quot;downstream&quot;, &quot;maxDepth&quot;: 50}&#39;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>startEntityId</code></td><td>required: a data object or a system (not a connection)</td></tr><tr><td><code>direction</code></td><td><code>downstream</code> (consumers), <code>upstream</code> (sources), <code>both</code> (the default, the union of both walks) or <code>impact</code> (<code>downstream</code> with <code>impact: true</code> on each node)</td></tr><tr><td><code>maxDepth</code></td><td>1 to 100, default 50 (<code>400</code> outside)</td></tr><tr><td><code>metatypeIds</code></td><td>at most 50 entity types (<code>400</code> above); keeps only the nodes of these types and their subtypes, the edges stay</td></tr><tr><td><code>dataObjectId</code></td><td>only for a start that is a system: follows only the flows that carry this data object</td></tr></tbody></table><p>From a <strong>data object</strong> the query follows the flows that carry it: <code>downstream</code> from their origins, <code>upstream</code> from their sinks. From a <strong>system</strong> it follows the flows from or to it, hop by hop. The answer lists the <code>nodes</code> (systems and tasks, with <code>depth</code> and <code>roles</code>: origin, intermediate, sink, reader, writer; the start is never a node), the <code>edges</code> (data flows, each with the data objects it carries in <code>carriedBy</code>, at most 50 with <code>carriedByTruncated</code>; and the data associations of tasks), the <code>paths</code> (at most 100) and the flags <code>cycleDetected</code> and <code>truncated</code>. At most 5000 nodes and 10000 edges are returned. Deleted entities are left out.</p><p>Errors: <code>404</code> for an unknown or deleted start, <code>422</code> for a connection as start, an unknown entity type in the filter or a <code>dataObjectId</code> that is no data object, and <code>422 LINEAGE_MODEL_INCOMPLETE</code> when the data object, the data flow or <em>Carries Data</em> is not set in the lineage model. The only property value returned is the <em>Transformation type</em> of a data output, and only if you may read it; otherwise the edge has <code>transformationRestricted: true</code>.</p><h2 id="find-data-flows-with-personal-data" tabindex="-1">Find data flows with personal data <a class="header-anchor" href="#find-data-flows-with-personal-data" aria-label="Permalink to “Find data flows with personal data”">​</a></h2><p>Create a <a href="./catalogs">catalog</a> of <em>Data Flow</em> entities, show the columns <em>Personal data categories</em> and <em>Protocol</em>, and filter by <em>Personal data categories is not empty</em> and, for example, <em>Protocol is JDBC</em>. A filter that matches nothing shows an empty table, not an error. An export of a catalog as CSV is not part of this release.</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};